const r = $json || {};
const nuevas = Number(r.nuevas_24h) || 0;
const proc = Number(r.procesadas_24h) || 0;
const backlog = Number(r.backlog_nuevas) || 0;
const abiertas = Number(r.abiertas) || 0;
const NL = String.fromCharCode(10);
const al = [];
if (nuevas === 0) al.push('- Sin ofertas NUEVAS ingeridas en 24h (scraper o RSS caido?)');
if (proc === 0) al.push('- Ninguna oferta puntuada en 24h (WF1 / worker / IA parados?)');
if (backlog > 50) al.push('- Backlog de ' + backlog + ' ofertas en estado nueva sin puntuar (scoring atascado?)');
if (!al.length) return [];
const text = '⚠️ Empleo IA - healthcheck' + NL + al.join(NL) + NL + '(nuevas24h=' + nuevas + ', procesadas24h=' + proc + ', backlog=' + backlog + ', abiertas=' + abiertas + ')';
return [{ json: { text: text } }];
